-- ===========================================================================
--  Cash-box transfer acceptance — database-level GRANT/REVOKE
--  Migration: CashBoxTransferAcceptance (client, 2026-10-12)
-- ===========================================================================
--
--  DO NOT EDIT THIS FILE. A migration is applied once and then frozen; a change
--  here would make new databases silently differ from old ones. A change needs a
--  new migration and a new .sql file (same rule as cash_boxes_guards.sql).
--
--  `cash_box_transfer_decisions` is a money record exactly like the transfer it
--  answers: an accepted transfer moved money, a returned one did not. Rewriting
--  or deleting the answer would rewrite both boxes' history, so `app_rw` may only
--  INSERT and SELECT — the same rule as `cash_box_transactions`. One answer per
--  transfer is the primary key.
--
--  No `app_rw` role (the test harness) — skip quietly, as the other guard files do.
-- ===========================================================================

DO $guards$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_rw') THEN
        RAISE NOTICE '[cash_box_transfer_decisions_guards] `app_rw` roli topilmadi — GRANT/REVOKE o''tkazib '
                     'yuborildi. deploy/init-roles.sql ni ishga tushiring.';
        RETURN;
    END IF;

    EXECUTE 'REVOKE UPDATE, DELETE, TRUNCATE ON public.cash_box_transfer_decisions FROM app_rw';
END
$guards$;
